css='''\n:root{--bg:#17191b;--panel:#25282b;--panel2:#303438;--line:#50565b;--accent:#239b58;--accent2:#4b88cf}\nbody{background:#17191b;color:#e9edef;font-family:Arial,Helvetica,sans-serif}.app{max-width:1120px;padding:13px 13px 34px}.top{margin:3px 2px 10px;padding-bottom:9px;border-bottom:1px solid #42484c}\n.logo{background:linear-gradient(145deg,#087d52,#17a66b);border-radius:3px;width:38px;height:38px}.brand h1{font-size:18px}.sub{font-size:9px}\n.classic-menu{position:relative;display:flex;align-items:center;gap:9px;padding:8px 10px;background:#202326;border:1px solid #484e53;border-bottom:0;border-radius:4px 4px 0 0;color:#aeb8bf;font-size:13px;z-index:7}.classic-menu>button{border:0;background:transparent;color:#e2e7ea;padding:3px 5px;font-size:13px;font-weight:700}\n.menu-panel{position:absolute;top:38px;left:6px;min-width:min(320px,calc(100vw - 36px));padding:13px;background:#292d30;border:1px solid #596167;border-radius:4px;box-shadow:0 8px 22px #0009;color:#edf1f2;z-index:20}.menu-actions{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-top:10px}\n.nav{position:relative;top:0;border-radius:0 0 4px 4px;background:#292d30;border-color:#484e53;grid-template-columns:repeat(5,minmax(0,1fr));gap:2px;padding:4px;box-shadow:none}.nav button{color:#c3cbd0;font-size:10px;text-transform:uppercase;padding:9px 3px;border-radius:3px}.nav button.active{background:#167c49;color:#fff;box-shadow:none}\n.card{background:#24282b;border:1px solid #51585d;border-radius:4px;padding:12px;box-shadow:none}.card h2{font-size:16px;border:0;padding:0}.label{font-size:12px;text-transform:none}.field{background:#111416;border:1px solid #697177;border-radius:3px}.field.big{background:#101315;border:2px solid #1d9856;border-radius:3px;font-size:20px;font-weight:500;min-height:48px}\n.calculator-actions{display:flex;gap:6px;align-items:center;flex-wrap:wrap;margin-top:9px}.calculator-actions .badge{margin-left:auto}.btn{border-radius:3px;padding:8px 10px;font-size:11px}.btn.primary{background:#147a45;border-color:#2aaf68}.btn.ghost{background:#30363a;border-color:#626b70;color:#e2e7e9}.section-head strong{font-size:12px;text-transform:uppercase;letter-spacing:.5px}\n#quick-stats.stat-grid{display:grid;grid-template-columns:repeat(var(--cipher-columns,4),minmax(0,1fr));gap:7px;margin:8px 0}.cipher-display-item{min-width:0;cursor:pointer;background:#1b1f21;border:1px solid #555e63;border-left:4px solid #4b91ce;border-radius:3px;padding:8px 10px;display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:54px;color:inherit;font:inherit;text-align:left}.cipher-display-item .cipher-title{font-size:11px;color:#e1e7ea;overflow-wrap:anywhere}.cipher-display-item .value{font-size:20px;font-weight:800;color:#8ab9f4;white-space:nowrap}.cipher-display-item .value.na{font-size:11px;color:#f0bd70}.cipher-display-item .cipher-root{display:block;font-size:9px;color:#aeb8be;margin-top:2px}\n.cipher-display-item:nth-child(10n+1){border-left-color:#43cc73}.cipher-display-item:nth-child(10n+1) .value{color:#54dd7e}.cipher-display-item:nth-child(10n+2){border-left-color:#648cff}.cipher-display-item:nth-child(10n+2) .value{color:#83a5ff}.cipher-display-item:nth-child(10n+3){border-left-color:#d77acb}.cipher-display-item:nth-child(10n+3) .value{color:#e69adb}.cipher-display-item:nth-child(10n+4){border-left-color:#e4c13b}.cipher-display-item:nth-child(10n+4) .value{color:#f2d55f}.cipher-display-item:nth-child(10n+5){border-left-color:#36c2d5}.cipher-display-item:nth-child(10n+5) .value{color:#62d5e2}.cipher-display-item:nth-child(10n+6){border-left-color:#e38d4f}.cipher-display-item:nth-child(10n+6) .value{color:#f2a66c}.cipher-display-item:nth-child(10n+7){border-left-color:#a587e8}.cipher-display-item:nth-child(10n+7) .value{color:#c1a8ff}.cipher-display-item:nth-child(10n+8){border-left-color:#d96d75}.cipher-display-item:nth-child(10n+8) .value{color:#ee8c94}.cipher-display-item:nth-child(10n+9){border-left-color:#67bfa1}.cipher-display-item:nth-child(10n+9) .value{color:#8ed7b8}.cipher-display-item:nth-child(10n){border-left-color:#c7d1d7}.cipher-display-item:nth-child(10n) .value{color:#e1eaee}\n.inner-tool{margin:10px 0 0;padding:10px;background:#1d2123}.letter-chart{display:grid;grid-template-columns:repeat(13,minmax(0,1fr));gap:4px}.chart-cell{background:#131719;border:1px solid #485157;border-radius:3px;text-align:center;padding:6px 2px}.chart-cell b{display:block;font-size:13px}.chart-cell span{font-size:10px;color:#91dba9}.cipher-group{border-radius:3px;border-color:#4d565c}.group-title{background:#343a3e;border-radius:0}.cipher-row{font-size:11px}.date-item{border-radius:3px}.table td,.table th{border-bottom-color:#40484d}\n@media(max-width:600px){.app{padding:9px 7px 28px}.nav button{font-size:9px;line-height:1.2;padding:8px 2px}.menu-panel{left:2px}#quick-stats.stat-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.cipher-display-item .value{font-size:17px}.letter-chart{grid-template-columns:repeat(7,minmax(0,1fr))}}\n@media(min-width:760px){.cipher-list{grid-template-columns:repeat(3,minmax(0,1fr))}}\n'''
