post='''\nrenderQuick=function(){const text=$('phrase').value;const names=[...homeCiphers].filter(n=>selected.has(n)&&allDefs.some(d=>d.name===n));if(!names.length){$('quick-stats').innerHTML='<div class=\"empty\">No displayed ciphers. Open Ciphers and tap ☆ beside a cipher.</div>';}else{$('quick-stats').innerHTML=names.map(n=>{const d=allDefs.find(x=>x.name===n),v=calc(text,d);return '<button type=\"button\" class=\"cipher-display-item\" data-home-breakdown=\"'+escapeHtml(n)+'\"><span><span class=\"cipher-title\">'+escapeHtml(n)+'</span><span class=\"cipher-root\">'+(v===null?'Chart unavailable':'Digital root '+dr(v))+'</span></span><span class=\"value '+(v===null?'na':'')+'\">'+(v===null?'N/A':v.toLocaleString())+'</span></button>'}).join('');$('quick-stats').querySelectorAll('[data-home-breakdown]').forEach(c=>c.addEventListener('click',()=>{$('breakdown-select').value=c.dataset.homeBreakdown;$('cipher-chart-select').value=c.dataset.homeBreakdown;renderBreakdown();renderCipherChart();$('breakdown-card').classList.remove('hidden');$('breakdown-card').scrollIntoView({behavior:'smooth',block:'center'})}));}$('calc-count').textContent=names.length+' displayed';};\nfunction renderCipherChart(){const d=allDefs.find(x=>x.name===$('cipher-chart-select').value)||allDefs[0];if(!d||!d.arr){$('cipher-chart-grid').textContent=d?.note||'Chart unavailable';return;}let h='';for(let i=0;i<26;i++){const ch=String.fromCharCode(97+i);h+='<div class=\"chart-cell\"><b>'+ch.toUpperCase()+'</b><span>'+getVal(d,ch)+'</span></div>';}$('cipher-chart-grid').innerHTML=h;}\nfunction closeMenus(){document.querySelectorAll('.menu-panel').forEach(p=>p.classList.add('hidden'));}\ndocument.querySelectorAll('[data-menu]').forEach(b=>b.addEventListener('click',()=>{const p=$('menu-'+b.dataset.menu);document.querySelectorAll('.menu-panel').forEach(x=>{if(x!==p)x.classList.add('hidden')});p.classList.toggle('hidden')}));\n$('menu-manage-ciphers').onclick=()=>{closeMenus();$('cipher-search').scrollIntoView({behavior:'smooth',block:'center'})};$('menu-base-ciphers').onclick=()=>{selected=new Set(['Ordinal','Reduction','Reverse Ordinal','Reverse Reduction']);renderAll();closeMenus()};$('menu-all-ciphers').onclick=()=>{allDefs.forEach(d=>selected.add(d.name));renderAll();closeMenus()};\nconst cols=Number(localStorage.getItem('gl_cipher_columns')||'4');$('cipher-columns').value=String([2,3,4,5,6].includes(cols)?cols:4);document.documentElement.style.setProperty('--cipher-columns',$('cipher-columns').value);$('cipher-columns').onchange=()=>{document.documentElement.style.setProperty('--cipher-columns',$('cipher-columns').value);localStorage.setItem('gl_cipher_columns',$('cipher-columns').value)};\n$('cipher-chart-select').innerHTML=allDefs.map(d=>'<option>'+escapeHtml(d.name)+'</option>').join('');$('cipher-chart-select').value='Ordinal';$('cipher-chart-select').onchange=renderCipherChart;\nfunction toggleChart(){const e=$('chart-card');e.classList.toggle('hidden');if(!e.classList.contains('hidden'))renderCipherChart()}function toggleBreakdown(){const e=$('breakdown-card');e.classList.toggle('hidden');if(!e.classList.contains('hidden'))renderBreakdown()}\n$('toggle-chart').onclick=toggleChart;$('menu-toggle-chart').onclick=()=>{closeMenus();toggleChart()};$('toggle-breakdown').onclick=toggleBreakdown;$('menu-toggle-breakdown').onclick=()=>{closeMenus();toggleBreakdown()};\ndocument.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenus();return;}const tag=(e.target.tagName||'').toLowerCase(),typing=['input','textarea','select'].includes(tag);if(e.key==='/'&&!typing){e.preventDefault();$('phrase').focus()}if(e.ctrlKey&&e.key==='Enter'&&$('view-ciphers').classList.contains('active')){e.preventDefault();historySave()}if(e.altKey&&e.key==='1')document.querySelector('[data-tab=\"dates\"]').click();if(e.altKey&&e.key==='2')document.querySelector('[data-tab=\"numbers\"]').click()});\nrenderAll();renderCipherChart();\n'''
rep('init();\\n</script>','init();\\n'+post+'</script>','post-init behaviour')
